import fs from 'node:fs/promises';import crypto from 'node:crypto';import assert from 'node:assert/strict';
import {S,H,volumeFeatures,FILTERS,BINS,excursion,modelSweep,metrics} from './research-short-squeeze-volume-20261107.mjs';
import {trade} from './research-dominance-model13.mjs';import {simulate} from './research-pump-high-whale-turn.mjs';
const dir='data/research/short-squeeze-volume-20261107',read=async p=>JSON.parse(await fs.readFile(p)),save=async(p,x)=>fs.writeFile(p,JSON.stringify(x)),hash=x=>crypto.createHash('sha256').update(x).digest('hex');
const m=await read(dir+'/manifest.json'),fetched=await read(dir+'/fetch-complete.json'),funding=await read(dir+'/funding.json'),events=await read(dir+'/events.json'),mature=events.filter(e=>e.entryAt+8*H<=m.end),cache=new Map();
assert.equal(hash(await fs.readFile(dir+'/runtime-signals-frozen.json')),m.eventHash);assert.equal(hash(await fs.readFile(dir+'/funding.json')),fetched.fundingHash);
async function raw(symbol){if(!cache.has(symbol)){const b=await fs.readFile(dir+'/raw/'+encodeURIComponent(symbol)+'-data.json');assert.equal(hash(b),fetched.rawHashes[symbol]);cache.set(symbol,JSON.parse(b));}return cache.get(symbol);}
const btc=await raw('BTCUSDT'),rows=[],coverage={},validation={independentTrades:0,futureModelInvariance:0,sourceChecks:0};let done=0;
for(const e of mature){const p=e.position;assert.ok(p.crowdLong>=60&&p.whaleDelta4hPp<0&&p.smartDelta4hPp<0&&p.whaleCount>=10);assert.ok(p.whaleAt<=e.decisionAt-15*60000&&p.whaleObservedAt<=e.availableAt&&p.previousWhaleObservedAt<=e.availableAt&&p.crowdAt<=e.decisionAt-15*60000);assert.ok(e.entryAt>e.availableAt&&e.decisionAt<=e.availableAt);validation.sourceChecks++;
const r=await raw(e.symbol),features=volumeFeatures(r,e,btc),fixed=trade(r.price,e,funding,m.end),independent=simulate(r.price,e.entryAt,-1,funding.filter(f=>f.symbol===e.symbol),m.end);
assert.equal(fixed.status==='OK',independent.status==='OK');if(fixed.status==='OK'){assert.ok(Math.abs(fixed.netRoe-independent.netRoe)<1e-9);assert.equal(fixed.kind,independent.kind);assert.equal(fixed.exitAt,independent.exitAt);validation.independentTrades++;}
const model=modelSweep(r,e,S),model10=modelSweep(r,e,2*S),move=excursion(r,e);coverage[model.status]=(coverage[model.status]??0)+1;
if(model.asOf)assert.ok(model.asOf<=e.decisionAt-S);if(model10.asOf)assert.ok(model10.asOf<=e.decisionAt-2*S);
if(done%30===0&&model.asOf){const modified=structuredClone(r);for(const k of ['price','mark'])for(const b of modified[k])if(+b[0]>=e.entryAt){for(const i of [1,2,3,4])b[i]=String(+b[i]*1.2);}for(const o of modified.oi)if(+o.timestamp>=e.decisionAt)o.sumOpenInterest=String(+o.sumOpenInterest*2);const alt=modelSweep(modified,e,S);assert.equal(JSON.stringify(alt.zone),JSON.stringify(model.zone));assert.equal(alt.asOf,model.asOf);validation.futureModelInvariance++;}
const phase=e.entryAt+8*H<=m.split?'TRAIN':e.availableAt>=m.split?'TEST':'PURGED';rows.push({...e,features,trade:fixed,excursion:move,model,model10,phase});done++;if(done%10===0){await save(dir+'/evaluate-progress.json',{done,total:mature.length,coverage,validation});console.log(JSON.stringify({done,total:mature.length,coverage}));}}
const eligible=rows.filter(r=>r.features.status==='OK'&&r.trade.status==='OK'&&r.excursion.status==='OK'),groups={};for(const [k,fn]of Object.entries(FILTERS)){const selected=eligible.filter(r=>fn(r.features));groups[k]={all:metrics(selected),rejected:metrics(eligible.filter(r=>!fn(r.features))),train:metrics(selected.filter(r=>r.phase==='TRAIN')),test:metrics(selected.filter(r=>r.phase==='TEST')),withoutBTCDown:metrics(selected.filter(r=>r.features.btc1h>=0)),btcDown:metrics(selected.filter(r=>r.features.btc1h<0))};}
const bins=Object.fromEntries(Object.entries(BINS).map(([k,fn])=>[k,metrics(eligible.filter(r=>fn(r.features)))]));assert.equal(Object.values(bins).reduce((s,v)=>s+v.n,0),eligible.length);
const distance={};for(const [name,fn]of Object.entries({'<1%':d=>d<1,'1–3%':d=>d>=1&&d<3,'>=3%':d=>d>=3})){const sample=eligible.filter(r=>r.model.status==='OK'&&fn(r.model.distancePct));distance[name]={lowVolume:metrics(sample.filter(r=>r.features.volume15m<1.5)),highVolume:metrics(sample.filter(r=>r.features.volume15m>=1.5))};}
let seed=20261107;const rand=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};function bootstrap(sample,filter,key,metric){const gs=new Map();for(const r of sample){const k=key(r);if(!gs.has(k))gs.set(k,[]);gs.get(k).push(r);}const a=[...gs.values()],out=[];for(let j=0;j<2000&&a.length>1;j++){const rs=[];for(let i=0;i<a.length;i++)rs.push(...a[Math.floor(rand()*a.length)]);const base=metric(rs),selected=metric(rs.filter(r=>filter(r.features)));if(base!==null&&selected!==null)out.push(selected-base);}out.sort((a,b)=>a-b);return{clusters:a.length,validReplicates:out.length,delta95:out.length?[out[Math.floor(out.length*.025)],out[Math.floor(out.length*.975)]]:null};}
const meanRoe=rs=>rs.length?rs.reduce((s,r)=>s+r.trade.netRoe,0)/rs.length:null,sweepPct=rs=>{const z=rs.filter(r=>r.model.status==='OK');return z.length?100*z.filter(r=>r.model.swept).length/z.length:null;},uncertainty={};
for(const k of Object.keys(FILTERS).filter(k=>k!=='ALL'))uncertainty[k]={roeCoin:bootstrap(eligible,FILTERS[k],r=>r.symbol,meanRoe),roe2h:bootstrap(eligible,FILTERS[k],r=>Math.floor(r.availableAt/(2*H)),meanRoe),sweepCoin:bootstrap(eligible,FILTERS[k],r=>r.symbol,sweepPct),sweep2h:bootstrap(eligible,FILTERS[k],r=>Math.floor(r.availableAt/(2*H)),sweepPct)};
const summary={version:m.version,manifest:m,counts:{retained:events.length,mature:mature.length,pending:events.length-mature.length,eligible:eligible.length,missingFeatures:rows.filter(r=>r.features.status!=='OK').length,missingTrades:rows.filter(r=>r.trade.status!=='OK').length,phases:Object.fromEntries(['TRAIN','TEST','PURGED'].map(p=>[p,eligible.filter(r=>r.phase===p).length]))},coverage,groups,bins,distance,uncertainty,validation};
await save(dir+'/results.json',{...summary,records:rows});await fs.writeFile(dir+'/summary.json',JSON.stringify(summary,null,2));await fs.writeFile(dir+'/validation.json',JSON.stringify({status:'PASS',...validation,rawHashesVerified:cache.size,netEngineAgreement:true,noFutureVolume:true,noFutureTarget:true,originalActualEventsOnly:true,affectsOrders:false},null,2));
console.log(JSON.stringify({stage:'COMPLETE',counts:summary.counts,coverage,groups:Object.fromEntries(Object.entries(groups).map(([k,v])=>[k,{all:v.all,test:v.test}]))}));

